-- Passage rg9-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('e1083313-f281-5516-b4ab-a092af8eabbf', 'rg9-theme-summary-p06', (select id from public.skills where slug = 'read-g9-theme-summary'), null,
        '9-12', $q$Before the Town Wakes$q$, $q$My father leaves the house at four
while all the streetlights still are on.
I hear the door, the careful key,
the engine coughing in the cold.

By five the ovens hold their heat.
He folds the dough the way he folds
my shirts on Sundays, without hurry,
a crease, a turn, a crease again.

The town is sleeping. No one sees
the flour settle on his sleeves,
the clock above the mixing bench,
the hundred loaves that rise in rows.

At seven, people hurry in.
They buy their rolls and count their change.
They do not ask who made the bread.
They do not have to. It is there.

I used to think that this was sad,
that all his work went out the door
in paper bags that bore no name,
and no one ever thanked him for it.

But now I think he likes it so.
The bread is warm. The town is fed.
The morning starts the way it should
because somebody woke at four.

Tonight I set my clock for four
and leave a note beside his keys:
Wake me up tomorrow. Show me how
to fold the dough without a hurry.$q$, 'draft')
