  ('98f05556-1c36-506f-8350-605cbf4982c1', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"Admitting a mistake, even one no one noticed, protects the trust others place in your work.","is_correct":true},{"text":"Field trips should end earlier in the day so that students are not rushed.","is_correct":false,"misconception_token":"too-narrow"},{"text":"A good grade on a report matters more than whether its information is accurate.","is_correct":false,"misconception_token":"opposite-of-theme"},{"text":"Rock samples should always be tagged with a station number and a date.","is_correct":false,"misconception_token":"topic-not-theme"}]$q$::jsonb, $q$Admitting a mistake, even one no one noticed, protects the trust others place in your work.$q$, $q$Keoni reports an error no one saw because people "would trust that line," and his honesty earns Dr. Fenwick's trust. The tagging choice describes a procedure, not the story's message.$q$, 'draft', 'c72ddb49-a2f2-590c-bd6d-77bc8f5c0dc1')
