  ('e1f9d059-5fad-5fd2-93db-fd8d09598648', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'medium',
   $q$Which choice is the best objective summary of the passage?$q$, $q$[{"text":"Keoni realizes he switched two sample tags, reports the error despite a teammate's doubts, and the geologist keeps the samples and invites his help.","is_correct":true},{"text":"Keoni labels rock samples at six stations along Miller Creek as it grows dark and the bus waits.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Careless Keoni ruins his group's samples, but he redeems himself with an honest and admirable email.","is_correct":false,"misconception_token":"includes-opinion"},{"text":"Keoni's group loses its A when Mr. Osei discovers the switched tags and reports them to the county.","is_correct":false,"misconception_token":"adds-false-detail"}]$q$::jsonb, $q$Keoni realizes he switched two sample tags, reports the error despite a teammate's doubts, and the geologist keeps the samples and invites his help.$q$, $q$The correct summary covers the mistake, the choice to report it, and the result. Keoni finds the error himself, not Mr. Osei, and nothing says the grade changes, so that choice adds false details.$q$, 'draft', 'c72ddb49-a2f2-590c-bd6d-77bc8f5c0dc1')
